"use client";

import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import DashboardLayout from "../../components/dashboard/DashboardLayout";
import DashboardPageWrapper from "../../components/dashboard/DashboardPageWrapper";
import { useAuth } from "@clerk/nextjs";

export default function Practices() {
  const { isLoaded: isAuthLoaded, userId } = useAuth();
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState("date");
  const [sortOrder, setSortOrder] = useState("desc");
  const [currentPage, setCurrentPage] = useState(1);
  const [practicesData, setPracticesData] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    currentPage: 1,
    totalPages: 1,
    totalCount: 0,
    hasNextPage: false,
    hasPrevPage: false
  });
  const [expandedPractice, setExpandedPractice] = useState(null);
  const [hoveredPractice, setHoveredPractice] = useState(null);
  const practiceListRef = useRef(null);

  // Fetch practice sessions from the API
  const fetchPracticeSessions = async () => {
    if (!isAuthLoaded || !userId) return;

    setIsLoading(true);
    try {
      // Build query parameters
      const params = new URLSearchParams({
        page: currentPage,
        limit: 10,
        sortBy: sortBy === "date" ? "analysisDate" :
                sortBy === "score" ? "recommendations.performance_assessment.overall_score" :
                sortBy === "duration" ? "voiceAnalysis.duration" : "analysisDate",
        sortOrder: sortOrder,
        search: searchQuery
      });

      const response = await fetch(`/api/practice-sessions?${params}`);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Failed to fetch practice sessions");
      }

      setPracticesData(data.sessions);
      setPagination(data.pagination);
    } catch (err) {
      console.error("Error fetching practice sessions:", err);
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  // Fetch data when component mounts or when dependencies change
  useEffect(() => {
    if (isAuthLoaded) {
      fetchPracticeSessions();
    }
  }, [isAuthLoaded, userId, currentPage, sortBy, sortOrder]);

  // Debounce search query changes
  useEffect(() => {
    const timer = setTimeout(() => {
      if (isAuthLoaded) {
        setCurrentPage(1); // Reset to first page on new search
        fetchPracticeSessions();
      }
    }, 500);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  // Format time for display
  const formatTime = (timeString) => {
    if (!timeString) return "";
    const date = new Date(timeString);
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  // Format relative time (e.g., "2 days ago")
  const formatRelativeTime = (dateString) => {
    if (!dateString) return "N/A";

    const date = new Date(dateString);
    const now = new Date();
    const diffInSeconds = Math.floor((now - date) / 1000);

    if (diffInSeconds < 60) return "just now";
    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)} minutes ago`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)} hours ago`;
    if (diffInSeconds < 604800) return `${Math.floor(diffInSeconds / 86400)} days ago`;
    if (diffInSeconds < 2592000) return `${Math.floor(diffInSeconds / 604800)} weeks ago`;

    return formatDate(dateString);
  };

  // Sort practices based on current sort settings
  const sortedPractices = [...practicesData].sort((a, b) => {
    if (sortBy === 'date') {
      return sortOrder === 'desc'
        ? new Date(b.timestamp) - new Date(a.timestamp)
        : new Date(a.timestamp) - new Date(b.timestamp);
    }
    if (sortBy === 'score') {
      return sortOrder === 'desc' ? b.score - a.score : a.score - b.score;
    }
    if (sortBy === 'duration') {
      return sortOrder === 'desc'
        ? b.durationSeconds - a.durationSeconds
        : a.durationSeconds - b.durationSeconds;
    }
    return 0;
  });

  // No longer using practice type counts for segmentation

  // Helper functions for UI
  const getScoreColor = (score) => {
    if (score >= 90) return "bg-green-900/30 text-green-400";
    if (score >= 80) return "bg-blue-900/30 text-blue-400";
    if (score >= 70) return "bg-yellow-900/30 text-yellow-400";
    return "bg-red-900/30 text-red-400";
  };

  const getPerformanceLevelColor = (level) => {
    if (!level) return "text-gray-400";

    const levelLower = level.toLowerCase();
    if (levelLower.includes('advanced') || levelLower.includes('expert'))
      return "text-green-400";
    if (levelLower.includes('intermediate'))
      return "text-blue-400";
    if (levelLower.includes('developing'))
      return "text-yellow-400";
    if (levelLower.includes('beginner') || levelLower.includes('novice'))
      return "text-orange-400";

    return "text-gray-400";
  };

  const getTypeIcon = (type) => {
    // Map practice types to icons
    switch (type) {
      case "high_score":
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-green-600" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
          </svg>
        );
      case "medium_score":
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" viewBox="0 0 20 20" fill="currentColor">
            <path d="M10 12a2 2 0 100-4 2 2 0 000 4z" />
            <path fillRule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
          </svg>
        );
      case "low_score":
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-red-600" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
          </svg>
        );
      default:
        return (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-purple-600" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
          </svg>
        );
    }
  };

  // Function to toggle expanded practice
  const toggleExpandPractice = (id) => {
    setExpandedPractice(expandedPractice === id ? null : id);
  };

  // Scroll to expanded practice
  useEffect(() => {
    if (expandedPractice && practiceListRef.current) {
      const expandedElement = document.getElementById(`practice-${expandedPractice}`);
      if (expandedElement) {
        // Smooth scroll to the expanded practice
        expandedElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [expandedPractice]);

  // Animation variants
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const cardVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: i => ({
      y: 0,
      opacity: 1,
      transition: {
        delay: i * 0.05,
        duration: 0.4,
        ease: [0.25, 0.1, 0.25, 1.0]
      }
    }),
    hover: {
      y: -5,
      boxShadow: "0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)",
      transition: {
        duration: 0.3,
        ease: "easeOut"
      }
    },
    tap: {
      y: 0,
      scale: 0.98,
      transition: {
        duration: 0.15
      }
    }
  };

  const expandedCardVariants = {
    collapsed: {
      height: 0,
      opacity: 0,
      transition: {
        duration: 0.3,
        ease: "easeInOut"
      }
    },
    expanded: {
      height: "auto",
      opacity: 1,
      transition: {
        duration: 0.5,
        ease: "easeInOut",
        staggerChildren: 0.1,
        delayChildren: 0.2
      }
    }
  };

  const expandedItemVariants = {
    collapsed: {
      opacity: 0,
      y: 10,
      transition: {
        duration: 0.2
      }
    },
    expanded: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.3
      }
    }
  };

  const paginationVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        delay: 0.5,
        duration: 0.4
      }
    }
  };

  return (
    <DashboardLayout>
      <DashboardPageWrapper title="My Practice Sessions" description="Review and analyze your speaking practice history">

          {/* Redesigned Search and Filters */}
          <motion.div
            className="bg-[#1A1B20] rounded-lg shadow-md border border-[#2C2D32]/80 p-6 mb-8"
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
              {/* Left side - Search with count */}
              <div className="flex items-center w-full md:w-auto">
                <div className="relative flex-grow md:max-w-md">
                  <input
                    type="text"
                    placeholder="Search practices..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-[#232429] text-gray-200 rounded-xl border border-[#2C2D32] focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all duration-300"
                  />
                  <div className="absolute left-4 top-3.5 text-purple-500">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
                    </svg>
                  </div>
                  <div className="absolute right-4 top-2 bg-[#2C2D32] px-2 py-1 rounded-full text-xs text-gray-300">
                    {pagination.totalCount || 0} sessions
                  </div>
                </div>
              </div>

              {/* Right side - Sort controls */}
              <div className="flex items-center gap-3 w-full md:w-auto">
                <div className="relative group flex-grow md:flex-grow-0">
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                    className="appearance-none w-full md:w-auto pl-4 pr-10 py-3 bg-[#232429] text-gray-200 rounded-xl border border-[#2C2D32] focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all duration-300"
                  >
                    <option value="date">Sort by Date</option>
                    <option value="score">Sort by Score</option>
                    <option value="duration">Sort by Duration</option>
                  </select>
                  <div className="absolute right-3 top-3.5 text-purple-500 pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </div>
                </div>

                <motion.button
                  onClick={() => setSortOrder(sortOrder === "desc" ? "asc" : "desc")}
                  className="p-3 bg-[#232429] text-gray-200 rounded-xl border border-[#2C2D32] hover:bg-[#2C2D32] focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all duration-300"
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  title={sortOrder === "desc" ? "Descending order" : "Ascending order"}
                >
                  <motion.div
                    animate={{ rotate: sortOrder === "desc" ? 0 : 180 }}
                    transition={{ duration: 0.3 }}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-purple-500" viewBox="0 0 20 20" fill="currentColor">
                      <path d="M3 3a1 1 0 000 2h11a1 1 0 100-2H3zM3 7a1 1 0 000 2h7a1 1 0 100-2H3zM3 11a1 1 0 100 2h4a1 1 0 100-2H3zM15 8a1 1 0 10-2 0v5.586l-1.293-1.293a1 1 0 00-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L15 13.586V8z" />
                    </svg>
                  </motion.div>
                </motion.button>
              </div>
            </div>
          </motion.div>

          {/* Practices List */}
          <motion.div
            className="bg-[#1A1B20] rounded-lg shadow-md border border-[#2C2D32]/80 p-6"
            variants={containerVariants}
            initial="hidden"
            animate="visible"
            ref={practiceListRef}
          >
            {isLoading ? (
              // Loading state with skeleton cards
              <div className="grid grid-cols-1 gap-6">
                {[...Array(3)].map((_, i) => (
                  <div key={i} className="bg-[#232429] rounded-lg p-6 animate-pulse">
                    <div className="flex items-center space-x-4">
                      <div className="h-12 w-12 rounded-full bg-[#2C2D32]"></div>
                      <div className="flex-1">
                        <div className="h-4 bg-[#2C2D32] rounded w-3/4 mb-2"></div>
                        <div className="h-3 bg-[#2C2D32] rounded w-1/2"></div>
                      </div>
                      <div className="h-8 w-16 bg-[#2C2D32] rounded-full"></div>
                    </div>
                  </div>
                ))}
              </div>
            ) : sortedPractices.length > 0 ? (
              <motion.div
                className="grid grid-cols-1 gap-6"
                variants={containerVariants}
              >
                {sortedPractices.map((practice, index) => (
                  <motion.div
                    key={practice.id}
                    id={`practice-${practice.id}`}
                    className={`relative overflow-hidden rounded-xl border ${
                      hoveredPractice === practice.id
                        ? "border-purple-500/50"
                        : "border-[#2C2D32]/80"
                    } bg-gradient-to-br from-[#232429] to-[#1A1B20] transition-all duration-300`}
                    variants={cardVariants}
                    custom={index}
                    whileHover="hover"
                    whileTap="tap"
                    onHoverStart={() => setHoveredPractice(practice.id)}
                    onHoverEnd={() => setHoveredPractice(null)}
                  >
                    {/* Main card content */}
                    <div
                      className="p-6 cursor-pointer"
                      onClick={() => toggleExpandPractice(practice.id)}
                    >
                      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        {/* Left side - Practice info */}
                        <div className="flex items-center">
                          <div className="flex-shrink-0 h-12 w-12 rounded-full bg-[#232429] flex items-center justify-center">
                            {getTypeIcon(practice.type || (practice.score >= 80 ? 'high_score' : practice.score >= 60 ? 'medium_score' : 'low_score'))}
                          </div>
                          <div className="ml-4">
                            <div className="text-base font-medium text-gray-200">{practice.title}</div>
                            <div className="text-sm text-gray-400 flex items-center mt-1">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1 text-gray-500" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
                              </svg>
                              {formatRelativeTime(practice.timestamp)}
                            </div>
                          </div>
                        </div>

                        {/* Right side - Stats */}
                        <div className="flex flex-wrap items-center gap-4">
                          {/* Duration */}
                          <div className="flex items-center bg-[#1A1B20]/80 px-3 py-1.5 rounded-lg">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5 text-blue-500" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
                            </svg>
                            <span className="text-sm text-gray-300">{practice.duration}</span>
                          </div>

                          {/* Word count */}
                          <div className="flex items-center bg-[#1A1B20]/80 px-3 py-1.5 rounded-lg">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5 text-yellow-500" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4zm2 6a1 1 0 011-1h6a1 1 0 110 2H7a1 1 0 01-1-1zm1 3a1 1 0 100 2h6a1 1 0 100-2H7z" clipRule="evenodd" />
                            </svg>
                            <span className="text-sm text-gray-300">{practice.wordCount || 0} words</span>
                          </div>

                          {/* Score */}
                          <div className={`flex items-center px-3 py-1.5 rounded-lg ${getScoreColor(practice.score)}`}>
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5" viewBox="0 0 20 20" fill="currentColor">
                              <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                            </svg>
                            <span className="text-sm font-medium">{practice.score}%</span>
                          </div>

                          {/* Expand indicator */}
                          <motion.div
                            className="ml-2 text-gray-400"
                            animate={{ rotate: expandedPractice === practice.id ? 180 : 0 }}
                            transition={{ duration: 0.3 }}
                          >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                              <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                            </svg>
                          </motion.div>
                        </div>
                      </div>
                    </div>

                    {/* Expanded content */}
                    <AnimatePresence>
                      {expandedPractice === practice.id && (
                        <motion.div
                          className="px-6 pb-6 pt-2 border-t border-[#2C2D32]/80"
                          variants={expandedCardVariants}
                          initial="collapsed"
                          animate="expanded"
                          exit="collapsed"
                        >
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* Left column */}
                            <div className="space-y-6">
                              {/* Performance metrics */}
                              <motion.div variants={expandedItemVariants} className="bg-[#232429] rounded-lg p-4">
                                <h4 className="text-sm font-medium text-gray-300 mb-3">Performance Metrics</h4>
                                <div className="grid grid-cols-2 gap-4">
                                  {/* Speaking Rate */}
                                  <div className="bg-[#1A1B20] rounded-lg p-3">
                                    <div className="text-xs text-gray-400 mb-1">Speaking Rate</div>
                                    <div className="text-base font-medium text-blue-400">{practice.speakingRate || "N/A"} wpm</div>
                                  </div>

                                  {/* Clarity Score */}
                                  <div className="bg-[#1A1B20] rounded-lg p-3">
                                    <div className="text-xs text-gray-400 mb-1">Clarity</div>
                                    <div className="text-base font-medium text-green-400">{practice.coherenceScore || "N/A"}</div>
                                  </div>

                                  {/* Vocabulary Richness */}
                                  <div className="bg-[#1A1B20] rounded-lg p-3">
                                    <div className="text-xs text-gray-400 mb-1">Vocabulary</div>
                                    <div className="text-base font-medium text-yellow-400">{practice.vocabularyRichness || "N/A"}</div>
                                  </div>

                                  {/* Filler Words */}
                                  <div className="bg-[#1A1B20] rounded-lg p-3">
                                    <div className="text-xs text-gray-400 mb-1">Filler Words</div>
                                    <div className="text-base font-medium text-red-400">{practice.fillerWordsCount || 0}</div>
                                  </div>
                                </div>
                              </motion.div>

                              {/* Transcript preview */}
                              {practice.transcription && (
                                <motion.div variants={expandedItemVariants} className="bg-[#232429] rounded-lg p-4">
                                  <h4 className="text-sm font-medium text-gray-300 mb-2">Transcript Preview</h4>
                                  <p className="text-sm text-gray-400 line-clamp-4">
                                    {practice.transcription}
                                  </p>
                                  <div className="mt-2">
                                    <button className="text-sm text-purple-500 hover:text-purple-400 transition-colors">
                                      View Full Transcript
                                    </button>
                                  </div>
                                </motion.div>
                              )}
                            </div>

                            {/* Right column */}
                            <div className="space-y-6">
                              {/* Performance level */}
                              <motion.div variants={expandedItemVariants} className="bg-[#232429] rounded-lg p-4">
                                <h4 className="text-sm font-medium text-gray-300 mb-2">Performance Level</h4>
                                <div className={`text-lg font-medium ${getPerformanceLevelColor(practice.performanceLevel)}`}>
                                  {practice.performanceLevel || "Not Available"}
                                </div>
                              </motion.div>

                              {/* Strengths */}
                              {practice.strengths && practice.strengths.length > 0 && (
                                <motion.div variants={expandedItemVariants} className="bg-[#232429] rounded-lg p-4">
                                  <h4 className="text-sm font-medium text-gray-300 mb-2">Strengths</h4>
                                  <ul className="space-y-1">
                                    {practice.strengths.slice(0, 3).map((strength, i) => (
                                      <li key={i} className="text-sm text-green-400 flex items-start">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5 mt-0.5 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                                          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                                        </svg>
                                        {strength}
                                      </li>
                                    ))}
                                  </ul>
                                </motion.div>
                              )}

                              {/* Growth Areas */}
                              {practice.growthAreas && practice.growthAreas.length > 0 && (
                                <motion.div variants={expandedItemVariants} className="bg-[#232429] rounded-lg p-4">
                                  <h4 className="text-sm font-medium text-gray-300 mb-2">Areas for Improvement</h4>
                                  <ul className="space-y-1">
                                    {practice.growthAreas.slice(0, 3).map((area, i) => (
                                      <li key={i} className="text-sm text-yellow-400 flex items-start">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1.5 mt-0.5 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                                          <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                                        </svg>
                                        {area}
                                      </li>
                                    ))}
                                  </ul>
                                </motion.div>
                              )}
                            </div>
                          </div>

                          {/* Action buttons */}
                          <motion.div
                            variants={expandedItemVariants}
                            className="mt-6 flex justify-end space-x-3"
                          >
                            <button className="px-4 py-2 bg-[#232429] text-gray-300 rounded-lg border border-[#2C2D32] hover:bg-[#2C2D32] transition-colors">
                              Download Report
                            </button>
                            <button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors">
                              View Full Analysis
                            </button>
                          </motion.div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
                ))}
              </motion.div>
            ) : (
              <motion.div
                className="py-12 text-center"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 0.5 }}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mx-auto text-gray-500 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <h3 className="text-xl font-medium text-gray-300 mb-2">No practices found</h3>
                <p className="text-gray-400 mb-6 max-w-md mx-auto">
                  {error ? `Error: ${error}` : "Try changing your search or filters, or start a new practice session."}
                </p>
                <button className="px-6 py-3 bg-gradient-to-r from-purple-600 to-purple-700 text-white rounded-lg shadow-lg hover:from-purple-700 hover:to-purple-800 transition-all duration-300 transform hover:scale-105">
                  Start a New Practice
                </button>
              </motion.div>
            )}

            {/* Pagination controls */}
            {!isLoading && sortedPractices.length > 0 && (
              <motion.div
                className="mt-8 flex justify-between items-center"
                variants={paginationVariants}
                initial="hidden"
                animate="visible"
              >
                <div className="text-sm text-gray-400">
                  Showing {((pagination.currentPage - 1) * 10) + 1} to {Math.min(pagination.currentPage * 10, pagination.totalCount)} of {pagination.totalCount} results
                </div>
                <div className="flex space-x-2">
                  <button
                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                    disabled={!pagination.hasPrevPage}
                    className={`p-2 rounded-lg border ${
                      pagination.hasPrevPage
                        ? "border-[#2C2D32] bg-[#232429] text-gray-300 hover:bg-[#2C2D32]"
                        : "border-[#2C2D32]/50 bg-[#1A1B20] text-gray-500 cursor-not-allowed"
                    } transition-colors`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                  </button>

                  {/* Page numbers */}
                  {[...Array(pagination.totalPages)].map((_, i) => {
                    // Only show current page, first, last, and pages around current
                    const pageNum = i + 1;
                    if (
                      pageNum === 1 ||
                      pageNum === pagination.totalPages ||
                      (pageNum >= pagination.currentPage - 1 && pageNum <= pagination.currentPage + 1)
                    ) {
                      return (
                        <button
                          key={pageNum}
                          onClick={() => setCurrentPage(pageNum)}
                          className={`w-10 h-10 rounded-lg border ${
                            pageNum === pagination.currentPage
                              ? "border-purple-500 bg-purple-900/30 text-purple-300"
                              : "border-[#2C2D32] bg-[#232429] text-gray-300 hover:bg-[#2C2D32]"
                          } transition-colors`}
                        >
                          {pageNum}
                        </button>
                      );
                    }

                    // Show ellipsis for skipped pages
                    if (
                      (pageNum === 2 && pagination.currentPage > 3) ||
                      (pageNum === pagination.totalPages - 1 && pagination.currentPage < pagination.totalPages - 2)
                    ) {
                      return (
                        <span key={pageNum} className="w-10 h-10 flex items-center justify-center text-gray-500">
                          ...
                        </span>
                      );
                    }

                    return null;
                  })}

                  <button
                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, pagination.totalPages))}
                    disabled={!pagination.hasNextPage}
                    className={`p-2 rounded-lg border ${
                      pagination.hasNextPage
                        ? "border-[#2C2D32] bg-[#232429] text-gray-300 hover:bg-[#2C2D32]"
                        : "border-[#2C2D32]/50 bg-[#1A1B20] text-gray-500 cursor-not-allowed"
                    } transition-colors`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                    </svg>
                  </button>
                </div>
              </motion.div>
            )}
          </motion.div>
      </DashboardPageWrapper>
    </DashboardLayout>
  );
}
